import{_ as e,o,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"1990年 · 悲观中的价值发现","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1990年.md","filePath":"05_quotes/by-year/1990年.md"}'),l={name:"05_quotes/by-year/1990年.md"};function u(q,t,s,h,c,_){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1990年-·-悲观中的价值发现" tabindex="-1">1990年 · 悲观中的价值发现 <a class="header-anchor" href="#_1990年-·-悲观中的价值发现" aria-label="Permalink to &quot;1990年 · 悲观中的价值发现&quot;">​</a></h1><blockquote><p>&quot;悲观带来低价，好公司降价才能买，这不代表逆向投资就是对，你还是要思考，不是说大家悲观你就买，你得思考。但是很多时候，悲观的时候才有好价格，乐观的时候价格高对你不好。&quot;——巴菲特（60岁）</p></blockquote><p>本页收录1990年致股东信中的经典语录。巴菲特在这一年逆势重仓富国银行，并系统阐述了&quot;透视盈利&quot;的真正含义，以及伯克希尔如何用浮存金的超低资金成本建立保险帝国的护城河。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;悲观带来低价，好公司降价才能买，这不代表逆向投资就是对，你还是要思考。不是说你悲观就买，很多悲观的时候还是有问题的，你要想清楚。但是悲观的时候确实有好价格，乐观的时候价格高，对你反而不好。&quot;</p></blockquote><blockquote><p>&quot;大家恐慌的时候我们捡便宜，大家开心我们不一定买。伯特兰·罗素说过，&#39;大多数人宁愿死也不愿思考&#39;，所以我们就是独立思考。&quot;</p></blockquote><blockquote><p>&quot;透视盈利就是：我们投资公司留存盈利，我们占有的部分，加上我们自己报告盈利，这样才算真实盈利。比如可口可乐用留存收益回购股票，我们持股比例就越来越高，我们持股内在价值就越来越高，本来可口可乐把钱分给我们，我们拿到还要交税，再买股票，肯定不如公司自己留着帮我们买。&quot;</p></blockquote><blockquote><p>&quot;浮存金成本等于承保亏损，除以平均浮存金。二十六年里有十九年我们资金成本低于长期国债收益率，十一年资金成本不到零，就是承保还赚钱，还给我们钱投资，这个结果真的很了不起。&quot;</p></blockquote><blockquote><p>&quot;我们宁愿要波动的15%，不要平稳的12%。&quot;</p></blockquote><blockquote><p>&quot;我们做巨灾再保险，资本够强，别人不敢接我们敢接，这就是我们竞争优势。价格现在大部分巨灾再保价格还是不对，但是只要灾难来临，价格就上来了。&quot;</p></blockquote><blockquote><p>&quot;银行业一般杠杆二十倍，一点点资产错误就能吃掉全部股权，过去很多大银行经理都犯这个错，大家跟着领导走，大家都杠杆，都给垃圾贷款，结果就是大家一起完蛋。&quot;</p></blockquote><blockquote><p>&quot;我们喜欢管理层，卡尔·赖卡特和保罗·黑曾，两个人加起来比单独一个强，都知道控制成本，盈利好的时候也不敢乱扩张，下跌的时候也敢理性面对。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1990年伯克希尔净值仅增长3.62亿美元，增幅7.3%，是近年最差表现之一。股价下跌23%，巴菲特年初的悲观预测应验。但正是在市场恐慌中，巴菲特大举买入富国银行，成本约2.89亿美元，占总股本10%。非保险业务ROE高达51%（财富500强前二十），Borsheim&#39;s销售增长18%成为全美单店珠宝销量冠军。GEICO浮存金成本持续低于零。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1990年-翻译-·-01-letters-1990年-核心总结-·-01-letters-1990年-思维导图" tabindex="-1"><a href="/01_letters/1990年/翻译.html">01_letters/1990年/翻译</a> · <a href="/01_letters/1990年/核心总结.html">01_letters/1990年/核心总结</a> · <a href="/01_letters/1990年/思维导图.html">01_letters/1990年/思维导图</a> <a class="header-anchor" href="#_01-letters-1990年-翻译-·-01-letters-1990年-核心总结-·-01-letters-1990年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1990年/翻译]] · [[→ 核心总结|01_letters/1990年/核心总结]] · [[→ 思维导图|01_letters/1990年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1990年/翻译.html">/01_letters/1990年/翻译</a></li></ul>',21)])])}const b=e(l,[["render",u]]);export{n as __pageData,b as default};
